#pragma once

#include <stdbool.h>
#include <stdint.h>
#include "esp_err.h"

/*
 * Bitmap fonts, ASCII 0x20..0x7E, 4-bit anti-aliased (0 = background .. 15 = ink).
 * Glyph data is generated by tools/mkfont.py (font_*.c). Each glyph is
 * 'height' rows of ceil(width/2) bytes, high nibble = left pixel; its width is
 * also its advance. Fonts are numbered 1..fontCount() (max FONT_MAX).
 *
 * Command registered by fontInit():
 *   FONT   list fonts as "n name height (fw|prop)"
 */

#define FONT_MAX	9
#define FONT_DEFAULT	1

typedef struct {
	const char     *name;
	uint8_t         height;		/* line height, pixels */
	uint8_t         baseline;	/* pixels from top to baseline */
	uint8_t         lead;		/* default extra pixels between lines */
	uint8_t         maxWidth;	/* widest glyph */
	bool            prop;		/* proportional (else fixed width) */
	uint8_t         first, last;	/* character range */
	const uint8_t  *widths;		/* per glyph */
	const uint32_t *offsets;	/* per glyph, into data */
	const uint8_t  *data;
} font_t;

/* Register FONT. Call after cmdInit(). */
esp_err_t fontInit(void);

int fontCount(void);

/* Font 1..fontCount(), or NULL. */
const font_t *fontGet(int id);

/* Glyph for c (unsupported characters give '?'); *width receives its width. */
const uint8_t *fontGlyph(const font_t *f, char c, int *width);

int fontCharWidth(const font_t *f, char c);

/* Alpha 0..15 of pixel (x, y) in a glyph of the given width. */
static inline uint8_t fontAlpha(const uint8_t *glyph, int width, int x, int y)
{
	uint8_t b = glyph[y * ((width + 1) >> 1) + (x >> 1)];
	return (x & 1) ? (b & 0x0F) : (b >> 4);
}
